# Use a SAT-based approach with pysat
# Variables: for each optional edge, whether it's included

from pysat.formula import CNF
from pysat.solvers import Solver
import networkx as nx
from itertools import combinations

fixed_edges = [(0,6), (1,10), (3,6), (3,8), (2,7), (0,4), (1,6), (0,8), (1,2), (5,10), (0,3)]
all_possible = [(u,v) for u in range(11) for v in range(u+1, 11)]
optional_edges = [e for e in all_possible if e not in fixed_edges]

# Variable numbering: edge index + 1 (1-indexed for SAT)
edge_to_var = {e: i+1 for i, e in enumerate(optional_edges)}
var_to_edge = {v: e for e, v in edge_to_var.items()}

n_vars = len(optional_edges)
print(f"Number of optional edge variables: {n_vars}")

# We need to encode:
# 1. Max independent set <= 4: for every subset of 5 vertices, at least one edge must exist
# 2. Vertex connectivity >= 3: for every pair of vertices and every set of 2 vertices (cut),
#    removing those 2 vertices doesn't disconnect the graph

# Constraint 1: No independent set of size 5
# For every 5-subset of vertices, at least one pair must be connected
cnf_clauses = []

def edge_var(u, v):
    """Return the SAT variable for edge (u,v), or True if it's a fixed edge, or None if not possible"""
    if u > v:
        u, v = v, u
    if (u, v) in fixed_edges:
        return None  # Always present (True)
    return edge_to_var.get((u, v))

# For each 5-subset, at least one edge must exist
count_is_clauses = 0
for subset in combinations(range(11), 5):
    clause = []
    has_fixed_edge = False
    for u, v in combinations(subset, 2):
        eu, ev = min(u,v), max(u,v)
        if (eu, ev) in fixed_edges:
            has_fixed_edge = True
            break
        else:
            var = edge_to_var.get((eu, ev))
            if var:
                clause.append(var)
    if not has_fixed_edge:
        cnf_clauses.append(clause)
        count_is_clauses += 1

print(f"Independent set clauses: {count_is_clauses}")
